import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    static final ReentrantLock lock = new ReentrantLock();
    static int balance = 0;

    static void deposit(int amt) throws InterruptedException {
        if (!lock.tryLock(100, TimeUnit.MILLISECONDS)) {
            System.out.println("timeout " + amt);
            return;
        }
        try {
            if (amt <= 0) throw new IllegalArgumentException("bad amount");
            balance += amt;
        } finally {
            lock.unlock();
        }
    }

    public static void main(String[] args) throws Exception {
        java.util.Scanner in = new java.util.Scanner(System.in);
        int a = in.nextInt(), b = in.nextInt();
        Thread t = new Thread(() -> {
            try { deposit(a); } catch (Exception e) { System.out.println("rejected " + a); }
        });
        t.start();
        t.join();
        try { deposit(b); } catch (IllegalArgumentException e) { System.out.println("rejected " + b); }
        System.out.println("Balance: " + balance);
    }
}
